             'auth_header':{'type':'string','enum':['Authorization','x-api-key','X-API-Key','api-key'],'default':'Authorization'},
             'auth_scheme':{'type':'string','enum':['Bearer',''],'default':'Bearer'}},['handle','path']),
        'clanker_request_payment':('Request an owner-only card and purchase approval form for the current local checkout. The backend captures its actual origin and checkout contents. Specify the exact merchant, items/quantities and final total including fees. Optional handle selects a saved card. No card details enter chat. Shared requests move to DM. End the turn while waiting; approval resumes it. Cloud browsers cannot receive card data.',
            {'checkout_url':{'type':'string','description':'Exact URL of the open HTTPS checkout tab in the private local browser.'},
             'merchant':{'type':'string','maxLength':120},'summary':{'type':'string','maxLength':1000},
             'amount_minor':{'type':'integer','description':'Final total including fees, in minor units: INR 699.00 is 69900 paise.'},
             'currency':{'type':'string','enum':['INR','USD','EUR','GBP','CAD','AUD'],'default':'INR'},
             'handle':{'type':'string','description':'Optional private saved-card handle for this checkout origin.'}},['checkout_url','merchant','summary','amount_minor']),
        'clanker_pay':('Execute the owner-approved purchase in the original local supervised checkout. The backend checks owner, conversation, browser, page contents and payment button and consumes approval before card fill and submission. Each purchase needs fresh approval; unknown outcomes cannot be replayed. A submitted result is not proof of payment: verify the merchant receipt. Bank approval may still need the owner.',
            {'request_id':{'type':'string'}},['request_id']),
        'clanker_vault_fill':('Fill the saved password directly into this task\'s supervised browser on its exact permitted origin. Type the metadata username yourself first. No secret is returned.',{'handle':{'type':'string'}},['handle']),
        'clanker_vault_enter_code':('Enter an authenticator or current verification code on the saved login origin. Without a setup key, send a private hosted one-time-code form and resume automatically after submission. No code or setup key is returned.',{'handle':{'type':'string'}},['handle']),
    }
    for name,(description,properties,required) in definitions.items():
        schema={'name':name,'description':description,'parameters':{'type':'object','properties':properties,'required':required,'additionalProperties':False}}
        ctx.register_tool(name,'clanker_browser',schema,lambda args,_name=name,**kwargs:execute(_name,args,**kwargs),description=description,emoji='🔐')
