            {'handle':{'type':'string'},'path':{'type':'string','description':'Relative path and optional query beginning with one slash.'},
             'method':{'type':'string','enum':['GET','POST','PUT','PATCH','DELETE','HEAD'],'default':'GET'},
             'body':{'description':'Optional JSON request body.'},'headers':{'type':'object','additionalProperties':{'type':'string'}},
